import{_ as i,o as l,c as n,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Everything You Wanted to Know About RadosGW - Orit Wassermann, Matt Benjamin","description":"","frontmatter":{"title":"Everything You Wanted to Know About RadosGW - Orit Wassermann, Matt Benjamin","date":"2018-04-23T00:00:00.000Z","updated":"2018-04-24T00:00:00.000Z","tags":["Ceph RGW","对象存储","分布式存储","多地域复制","性能优化"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Everything_You_Wanted_to_Know_About_RadosGW_-_Orit_Wassermann_Matt_Benjamin.md","filePath":"posts/2018/Everything_You_Wanted_to_Know_About_RadosGW_-_Orit_Wassermann_Matt_Benjamin.md","lastUpdated":1780459816000}'),e={name:"posts/2018/Everything_You_Wanted_to_Know_About_RadosGW_-_Orit_Wassermann_Matt_Benjamin.md"};function s(a,t,r,_,p,g){return l(),n("div",null,[...t[0]||(t[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph RadosGW 分布式存储系统概述与未来规划</p><p><strong>会议时间</strong>： 2023年10月10日</p><p><strong>会议地点</strong>： 远程</p><p><strong>参会人员</strong>： Joseph Lanza、Benjamin、Matthew、其他研发人员</p><p><strong>会议内容</strong>：</p><p><strong>一、对象存储概述</strong></p><ul><li>对象存储位于块存储和文件系统之间，专为大规模对象和大量数据设计。</li><li>对象组织在桶或容器中，桶不能包含其他桶。</li><li>对象不可变，允许多副本存储，提高扩展性。</li><li>支持版本控制和生命周期管理，方便数据恢复和存储优化。</li></ul><p><strong>二、Ceph 对象存储（RGW）功能</strong></p><ul><li>支持S3接口，使用REST API进行访问。</li><li>支持多部分上传，提高大文件上传效率。</li><li>支持版本控制，方便数据恢复。</li><li>支持生命周期管理，自动清理旧版本数据。</li><li>支持多地域复制，提高数据可用性和容错性。</li></ul><p><strong>三、Ceph RGW 未来规划</strong></p><ul><li><strong>多地域复制</strong>： <ul><li>支持跨不同地域的数据同步。</li><li>支持数据转换和格式转换。</li><li>支持双向同步。</li></ul></li><li><strong>性能优化</strong>： <ul><li>使用异步I/O提高性能。</li><li>引入调度器，智能管理流量。</li><li>优化桶索引结构，提高查询效率。</li></ul></li><li><strong>一致性保证</strong>： <ul><li>改进缓存一致性机制。</li><li>支持跨集群一致性保证。</li></ul></li><li><strong>安全特性</strong>： <ul><li>支持基于令牌的认证。</li><li>支持Kerberos认证。</li><li>支持桶级访问控制。</li></ul></li></ul><p><strong>四、行动计划</strong></p><ul><li>继续推进多地域复制功能。</li><li>优化Ceph RGW性能。</li><li>改进数据一致性保证。</li><li>加强安全特性。</li><li>完善文档和测试。</li></ul><p><strong>五、其他</strong></p><ul><li>会议还讨论了Ceph RGW与其他组件的集成，例如CephFS和Ceph Mon。</li><li>会议强调了持续集成和持续部署的重要性。</li></ul><p><strong>关键词</strong>： 对象存储、Ceph RGW、多地域复制、性能优化、一致性保证、安全特性、异步I/O、调度器、桶索引、缓存一致性、令牌认证、Kerberos认证、桶级访问控制</p>',17)])])}const W=i(e,[["render",s]]);export{d as __pageData,W as default};
